def main():
 assert set(b.DATA)=={f'a{x}' for x in range(126,136)}
 used={x for cfg in b.DATA.values() for x in cfg['refs']}|{'imec-venue','imec-history','imec-cooling'}
 out=dict(courses=[b.build_course(cid,cfg) for cid,cfg in b.DATA.items()],sources=[b.SOURCES[x] for x in sorted(used)],places=[b.build_place(cid,cfg) for cid,cfg in b.DATA.items()],related=[b.build_related(cid,cfg) for cid,cfg in b.DATA.items()])
 # The shared helper uses a fixed prefix internally; remap IDs consistently for this batch.
 out=json.loads(json.dumps(out,ensure_ascii=False).replace('v9b-','v9at-'))
 for c in out['courses']:
  assert len(c['stages'])==4 and all(len(s['steps'])==6 for s in c['stages'])
  for st in c['stages']:
   for s in st['steps']:
    assert len(s['knowledge'])>=2
    for k in ['title','objective','instruction','observation','failure','check']:assert s[k] and s[k+'En']
    assert len(s['quiz']['options'])==3 and 0<=s['quiz']['answer']<3
 for filename in ['build_group_a_tail.py','build_group_b.py']:
  ast.parse(Path(__file__).with_name(filename).read_text(),feature_version=(3,10))
 dest=Path(__file__).with_name('group_a_tail.json');dest.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps(dict(path=str(dest),courses=len(out['courses']),steps=sum(c['stepCount'] for c in out['courses']),knowledgePoints=sum(len(s['knowledge']) for c in out['courses'] for st in c['stages'] for s in st['steps']),sources=len(out['sources']),related=sum(len(x['related']) for x in out['related'])),ensure_ascii=False))
if __name__=='__main__':main()
